// Static taxonomy for the seed: industries, their representative Taiwan-listed
// stocks, and their industry-specific leading indicators.
//
// IMPORTANT: Tickers and company names here are real Taiwan-listed identifiers,
// but every *numeric* value produced by the seeder (prices, volumes, indicator
// levels, institutional flows) is SYNTHETIC DEMO DATA generated by a seeded
// PRNG. Nothing here is real market data — rows are flagged `isMock: true` and
// the UI surfaces that provenance.

export interface SeedIndicator {
  key: string;
  name: string;
  unit: string | null;
  frequency: "daily" | "weekly" | "monthly" | "quarterly";
  higherIsBetter: boolean;
  /** Starting level for the synthetic history. */
  baseValue: number;
  /** Per-period volatility, in percent. */
  volatilityPct: number;
  /** Per-period drift, in percent. Positive = improving trend. */
  driftPct: number;
  description: string;
}

export interface SeedStock {
  ticker: string;
  name: string;
  nameZh: string;
  exchange?: "TWSE" | "TPEx";
  /** Finer classification inside the parent industry, driving the 細產業 tab
   *  of the Industry Momentum module. Unlike every numeric value in this file
   *  these are real classifications, not synthetic demo values. */
  subIndustry: string;
  subIndustryZh: string;
  basePrice: number;
  mainCatalyst: string;
  mainRisk: string;
}

export interface SeedIndustry {
  slug: string;
  name: string;
  nameZh: string;
  description: string;
  thesis: string;
  cyclePosition: "early" | "expansion" | "peak" | "contraction" | "trough";
  riskLevel: "low" | "medium" | "high";
  /** Drives the synthetic score/flow bias so the demo shows real dispersion. */
  strengthBias: number; // -1 (weak) .. +1 (strong)
  stocks: SeedStock[];
  indicators: SeedIndicator[];
  catalysts: Array<{ title: string; description: string; importance: "high" | "medium" | "low"; daysAgo: number }>;
  risks: string[];
}

